IF NOT EXISTS (SELECT 1 FROM sys.check_constraints WHERE [name] = N'CK_OwnerAssignment_OneSubject' AND [parent_object_id] = OBJECT_ID(N'[ops].[OwnerAssignment]'))
    ALTER TABLE [ops].[OwnerAssignment] WITH CHECK ADD CONSTRAINT [CK_OwnerAssignment_OneSubject] CHECK
    (
        CASE WHEN NULLIF(JSON_VALUE([Columns], N'$.businessApplication'), N'') COLLATE Latin1_General_BIN2 IS NULL THEN 0 ELSE 1 END
        + CASE WHEN NULLIF(JSON_VALUE([Columns], N'$.subjectDataDomain'), N'') COLLATE Latin1_General_BIN2 IS NULL THEN 0 ELSE 1 END
        + CASE WHEN NULLIF(JSON_VALUE([Columns], N'$.subjectDataLocation'), N'') COLLATE Latin1_General_BIN2 IS NULL THEN 0 ELSE 1 END = 1
        AND
        (
            (NULLIF(JSON_VALUE([Columns], N'$.subjectKind'), N'') COLLATE Latin1_General_BIN2 IS NULL AND NULLIF(JSON_VALUE([Columns], N'$.businessApplication'), N'') COLLATE Latin1_General_BIN2 IS NOT NULL)
            OR (NULLIF(JSON_VALUE([Columns], N'$.subjectKind'), N'') COLLATE Latin1_General_BIN2 = N'business-application' AND NULLIF(JSON_VALUE([Columns], N'$.businessApplication'), N'') COLLATE Latin1_General_BIN2 IS NOT NULL)
            OR (NULLIF(JSON_VALUE([Columns], N'$.subjectKind'), N'') COLLATE Latin1_General_BIN2 = N'data-domain' AND NULLIF(JSON_VALUE([Columns], N'$.subjectDataDomain'), N'') COLLATE Latin1_General_BIN2 IS NOT NULL)
            OR (NULLIF(JSON_VALUE([Columns], N'$.subjectKind'), N'') COLLATE Latin1_General_BIN2 = N'data-location' AND NULLIF(JSON_VALUE([Columns], N'$.subjectDataLocation'), N'') COLLATE Latin1_General_BIN2 IS NOT NULL)
        )
    );
GO

