DECLARE @deny nvarchar(max);
SELECT @deny = STRING_AGG(CAST(N'DENY SELECT ON ' + QUOTENAME(s.[name]) + N'.' + QUOTENAME(o.[name]) + N' TO [product_app];' AS nvarchar(max)), NCHAR(10))
FROM
(
    SELECT h.[schema_id], h.[name] FROM sys.tables AS t JOIN sys.tables AS h ON h.[object_id] = t.[history_table_id]
    WHERE SCHEMA_NAME(t.[schema_id]) IN (N'config', N'ops', N'audit')
    UNION ALL
    SELECT v.[schema_id], v.[name] FROM sys.tables AS t JOIN sys.views AS v ON v.[object_id] = t.[ledger_view_id]
    WHERE SCHEMA_NAME(t.[schema_id]) IN (N'config', N'ops', N'audit')
) AS o
JOIN sys.schemas AS s ON s.[schema_id] = o.[schema_id];
IF @deny IS NOT NULL EXEC sys.sp_executesql @deny;
GO
